package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	var s string
	fmt.Fscan(in, &s)

	seattleToSF := 0
	sfToSeattle := 0

	for i := 0; i < n-1; i++ {
		if s[i] == 'S' && s[i+1] == 'F' {
			seattleToSF++
		} else if s[i] == 'F' && s[i+1] == 'S' {
			sfToSeattle++
		}
	}

	if seattleToSF > sfToSeattle {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

